--
-- Table structure for table `adm_clientes`
--

DROP TABLE IF EXISTS `adm_clientes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adm_clientes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `nombre_comercial` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `cedula` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `fecha_at` datetime DEFAULT NULL,
  `fecha_in` datetime DEFAULT NULL,
  `fecha_nac` date DEFAULT NULL,
  `sexo` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `adm_tipo_estatus_id` int NOT NULL,
  `telefono1` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `telefono2` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `telefono3` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `direccion` varchar(600) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `direccion_fisica` varchar(600) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `horario` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `descuento` decimal(12,2) DEFAULT '0.00',
  `adm_grupo_cliente_id` int NOT NULL DEFAULT '1',
  `limite_credito` int DEFAULT NULL,
  `tarifa` varchar(2) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `contribuyente` varchar(3) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `adm_cobrador_id` int DEFAULT NULL,
  `adm_vendedor_id` int DEFAULT NULL,
  `adm_zonas_id` int DEFAULT NULL,
  `correo_electronico` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `correo_electronico2` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `pag_web` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `dias_credito` int DEFAULT NULL,
  `creditos` decimal(16,8) DEFAULT NULL,
  `contacto` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `telefono_contacto` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `observacion` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `adm_estado_id` int NOT NULL DEFAULT '16',
  `adm_ciudad_id` int NOT NULL DEFAULT '331',
  `empleado` int DEFAULT NULL,
  `imagen` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'entity.jpg',
  `usuario_id` int DEFAULT '0',
  `vista_observ` tinyint(1) DEFAULT '0',
  `codigo_sicm` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `exis_afiliado` tinyint DEFAULT '0',
  `last_http_status` int DEFAULT NULL COMMENT 'ultimo codigo http que arrojo la aftim apii con dicho registro (importante que la data de envio no contenga este campo) ',
  `codigo_sucursal` varchar(16) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'codigo de la sede donde proviene la operacion (importante: agregar el codigo de la sucursal enviadora en el metodo de envio del erp)',
  `clave_wallet` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `limite_credito_dolar` decimal(16,8) DEFAULT '0.00000000',
  `nombre_proyecto` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `codigo` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `dias_atencion` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `adm_tipo_cliente_id` int DEFAULT NULL,
  `fechas_atencion` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `balance_coins` decimal(10,2) DEFAULT '0.00',
  `carrito_producto` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `cont_plan_cuentasxcobrar_id` int DEFAULT NULL,
  `cont_plan_notasdecredito_id` int DEFAULT NULL,
  `cont_plan_notasdedebito_id` int DEFAULT NULL,
  `cont_plan_iva_id` int DEFAULT NULL,
  `cont_plan_islr_id` int DEFAULT NULL,
  `cont_plan_anticipos_id` int DEFAULT NULL,
  `cont_plan_retencion_iva_id` int DEFAULT NULL,
  `cont_plan_descuento_id` int DEFAULT NULL,
  `servicio_pago_tercero` int DEFAULT NULL,
  `maximo_facturas_vencidas` int DEFAULT NULL,
  `bloquear_pedidos_maximo_facturas_vencidas` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cedula` (`cedula`,`codigo`) USING BTREE,
  KEY `adm_cobrador` (`adm_cobrador_id`) USING BTREE,
  KEY `adm_tipo_cliente` (`adm_tipo_cliente_id`) USING BTREE,
  CONSTRAINT `adm_cobrador` FOREIGN KEY (`adm_cobrador_id`) REFERENCES `adm_cobrador` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `adm_tipo_cliente` FOREIGN KEY (`adm_tipo_cliente_id`) REFERENCES `adm_tipo_cliente` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

