  `precio_b` decimal(18,5) DEFAULT NULL,
  `precio_c` decimal(18,5) DEFAULT NULL,
  `precio_d` decimal(18,5) DEFAULT NULL,
  `precio_e` decimal(18,5) DEFAULT NULL,
  `precio_f` decimal(18,5) DEFAULT NULL,
  `precio_g` decimal(18,5) DEFAULT NULL,
  `precio_h` decimal(18,5) DEFAULT NULL,
  `precio_i` decimal(18,5) DEFAULT NULL,
  `precio_j` decimal(18,5) DEFAULT NULL,
  `precio_k` decimal(18,5) DEFAULT NULL,
  `precio_dolar` decimal(18,5) DEFAULT '1.00000',
  `utilidad` decimal(18,5) DEFAULT NULL,
  `utilidad_a` decimal(18,5) DEFAULT NULL,
  `utilidad_b` decimal(18,5) DEFAULT NULL,
  `utilidad_c` decimal(18,5) DEFAULT NULL,
  `utilidad_d` decimal(18,5) DEFAULT NULL,
  `utilidad_e` decimal(18,5) DEFAULT NULL,
  `utilidad_f` decimal(18,5) DEFAULT NULL,
  `utilidad_g` decimal(18,5) DEFAULT NULL,
  `utilidad_h` decimal(18,5) DEFAULT NULL,
  `utilidad_i` decimal(18,5) DEFAULT NULL,
  `utilidad_j` decimal(18,5) DEFAULT NULL,
  `utilidad_k` decimal(18,5) DEFAULT NULL,
  `utilidad_dolar` decimal(18,5) DEFAULT '1.00000',
  `costo_dolar` decimal(18,5) DEFAULT '1.00000',
  `precio_variable` smallint DEFAULT '0',
  `retiene` tinyint(1) NOT NULL DEFAULT '0',
  `farm_principio_activo_id` int DEFAULT '0',
  `imagen` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `costo_adicional` decimal(30,12) DEFAULT NULL,
  `costo_adicional2` decimal(30,12) DEFAULT NULL,
  `cant_ensamblado` decimal(30,12) NOT NULL,
  `licor` tinyint(1) DEFAULT '0',
  `porcentaje` decimal(4,2) DEFAULT '0.00',
  `visible_pv` tinyint(1) DEFAULT '1',
  `visible_web` tinyint(1) DEFAULT '0',
  `rest_areas_id` int DEFAULT '1',
  `setcortesia` tinyint(1) DEFAULT '0',
  `exento` tinyint(1) DEFAULT '0',
  `merma` tinyint(1) DEFAULT '0',
  `iva` tinyint(1) DEFAULT '0',
  `tipo_origen` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '0',
  `maneja_lote` tinyint(1) DEFAULT '0',
  `existencia_c` decimal(12,3) DEFAULT NULL,
  `obviar_ajuste` tinyint(1) DEFAULT '0',
  `eludir_existencia` tinyint(1) DEFAULT '0',
  `garantia` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'N/A',
  `visible_fuerza_venta` tinyint DEFAULT '0',
  `iva_dolar` decimal(18,5) DEFAULT '0.00000',
