  `puntos_canjeables` decimal(10,2) DEFAULT '0.00' COMMENT 'Puntos de fidelidad canjeables en caja',
  `maneja_puntos` tinyint DEFAULT '0' COMMENT 'Condicional para decir si maneja fidelidad o no',
  `cont_plan_compras_id` int DEFAULT NULL,
