  `cont_plan_ingresos_id` int DEFAULT NULL,
  `sufijo_centro_costo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `dia_de_corte` int DEFAULT '0' COMMENT 'Valor por defecto 0, Mayor a 0 son dias de vencimiento para Tarjeta Mensuales Parking',
  `sambil_online_product_id` bigint DEFAULT NULL,
