  KEY `productos_ibfk_6` (`adm_unidades_id`) USING BTREE,
  KEY `productos_ibfk_7` (`adm_marcas_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=135 DEFAULT CHARSET=utf8mb3 COMMENT='Productos del Sistema';
