/*!50003 CREATE*/ /*!50017 DEFINER=`ss_oficina`@`170.81.146.209`*/ /*!50003 TRIGGER `after_product_price_update` AFTER UPDATE ON `adm_conceptos` FOR EACH ROW BEGIN
    DECLARE porcentaje_iva DECIMAL(10, 2); -- Declara una variable para almacenar el porcentaje de IVA

    -- Consulta el valor de la columna `porcentaje` desde `adm_iva` con una referencia a `iva`
    SELECT porcentaje 
    INTO porcentaje_iva
    FROM adm_iva
    WHERE id = NEW.iva;

	-- Verificar si el precio cambia
    IF (
        (NEW.precio_dolar != OLD.precio_dolar) || (NEW.precio_a != OLD.precio_a) 
        || (NEW.precio_b != OLD.precio_b) 
        || (NEW.precio_c != OLD.precio_c) 
        || (NEW.precio_d != OLD.precio_d) 
        || (NEW.precio_e != OLD.precio_e) 
        || (NEW.precio_f != OLD.precio_f) 
        || (NEW.precio_g != OLD.precio_g) 
        || (NEW.precio_h != OLD.precio_h) 
        || (NEW.precio_i != OLD.precio_i) 
        || (NEW.precio_j != OLD.precio_j) 
        || (NEW.precio_k != OLD.precio_k) 
	) THEN
        INSERT 
			INTO cambio_precios (
                adm_conceptos_id, porcentaje_iva,
                costo_anterior, costo_anterior_dolar, 
                nuevo_costo, nuevo_costo_dolar, 
                precio_a, precio_dolar, 
                precio_b, precio_c, 
                precio_d, precio_e, 
                precio_f, precio_g, 
                precio_h, precio_i, 
                precio_j, precio_k, 
                nuevo_precio_a, nuevo_precio_dolar, 
                nuevo_precio_b, nuevo_precio_c, 
                nuevo_precio_d, nuevo_precio_e, 
                nuevo_precio_f, nuevo_precio_g, 
                nuevo_precio_h, nuevo_precio_i, 
                nuevo_precio_j, nuevo_precio_k
            )
        VALUES (
            NEW.id, porcentaje_iva,
            OLD.ultimo_costo, OLD.costo_dolar, 
            NEW.ultimo_costo, NEW.costo_dolar, 
            OLD.precio_a, OLD.precio_dolar, 
            OLD.precio_b, OLD.precio_c, 
            OLD.precio_d, OLD.precio_e, 
            OLD.precio_f, OLD.precio_g, 
            OLD.precio_h, OLD.precio_i, 
            OLD.precio_j, OLD.precio_k, 
            NEW.precio_a, NEW.precio_dolar, 
            NEW.precio_b, NEW.precio_c, 
            NEW.precio_d, NEW.precio_e, 
