-- Table structure for table `adm_det_facturas`
--

DROP TABLE IF EXISTS `adm_det_facturas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adm_det_facturas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `adm_enc_facturas_id` int NOT NULL,
  `adm_conceptos_id` int NOT NULL,
  `adm_depositos_id` int NOT NULL,
  `adm_vendedor_id` int NOT NULL,
  `costo` decimal(30,12) NOT NULL,
  `costo_dolar` decimal(18,5) DEFAULT '1.00000',
  `precio` decimal(30,12) NOT NULL,
  `precio_dolar` decimal(18,5) DEFAULT '1.00000',
  `precio_base` decimal(30,12) DEFAULT '0.000000000000',
  `precio_baseDolar` decimal(18,5) DEFAULT '0.00000',
  `descuentopro` decimal(30,12) DEFAULT '0.000000000000',
  `descuentopar` decimal(30,12) DEFAULT '0.000000000000',
  `descuentoDol_par` decimal(18,5) DEFAULT '0.00000',
  `iva` decimal(30,12) DEFAULT NULL,
  `iva_dolar` decimal(18,5) DEFAULT NULL,
  `fecha_at` date DEFAULT NULL,
  `cantidad` decimal(12,4) NOT NULL,
  `despachado` int DEFAULT NULL,
  `devuelto` tinyint DEFAULT '0',
  `adm_seriales_id` int DEFAULT '0',
  `monto_documento` decimal(30,12) DEFAULT '0.000000000000',
  `adm_lotes_id` int DEFAULT NULL,
  `observacion_caract` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `devuelto_parcial` decimal(12,4) DEFAULT NULL,
  `adm_series_facturas_id` int DEFAULT '0',
  `recargo` decimal(30,12) DEFAULT NULL,
  `recargo_dolar` decimal(18,5) DEFAULT NULL,
  `tarifa` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `adm_color_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `adm_talla_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `modificador` decimal(18,5) DEFAULT NULL COMMENT 'cantidad equivalente proveniente de adm_unidades_equivalentes/adm_presentaciones',
  `nombre_modificador` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'nombre de la equivalencia proveniente de adm_unidades_equivalentes/adm_presentaciones',
  `piezas` decimal(12,2) DEFAULT '0.00',
  `cardNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '0.00',
  `adm_empresa_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `enc_facturas_id` (`adm_enc_facturas_id`) USING BTREE,
  KEY `productos_id` (`adm_conceptos_id`) USING BTREE,
  KEY `enc_facturas_id_2` (`adm_enc_facturas_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Detalle de las Facturas';
/*!40101 SET character_set_client = @saved_cs_client */;

