CREATE TABLE `adm_enc_facturas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_factura` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `numero_fiscal` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `serial_impresora` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `fecha_at` datetime NOT NULL,
  `fecha_in` date DEFAULT NULL,
  `adm_vendedor_id` int NOT NULL,
  `adm_clientes_id` int NOT NULL,
  `subtotal` decimal(30,12) NOT NULL,
  `subtotal_dolar` decimal(18,5) DEFAULT NULL,
  `descuento_global` decimal(30,3) DEFAULT NULL,
  `descuento_global_dolar` decimal(30,3) DEFAULT NULL,
  `descuento` decimal(30,12) DEFAULT NULL,
  `descuento_dolar` decimal(18,5) DEFAULT NULL,
  `recargo_dolar` decimal(18,5) DEFAULT '0.00000',
  `recargo` decimal(30,12) DEFAULT '0.000000000000',
  `iva` decimal(30,12) NOT NULL,
  `iva_dolar` decimal(18,5) DEFAULT '0.00000',
  `facturado` tinyint(1) NOT NULL,
  `estatus_pago` tinyint(1) NOT NULL,
  `despacho_autorizado` tinyint(1) DEFAULT '0',
  `abono` decimal(30,12) DEFAULT '0.000000000000',
  `abono_dolar` decimal(18,5) DEFAULT '0.00000',
  `monto_comision` decimal(30,12) DEFAULT '0.000000000000' COMMENT 'Contador para llevar rastro de los pagos de los % de comision a los vendedores',
  `monto_dolar_comision` decimal(30,12) DEFAULT '0.000000000000' COMMENT 'Contador para llevar rastro de los pagos en dolar de los % de comision a los vendedores',
  `devolucion` decimal(30,12) DEFAULT '0.000000000000',
  `devolucion_dolar` decimal(18,5) DEFAULT '0.00000',
  `exento` decimal(30,12) DEFAULT '0.000000000000',
  `exento_dolar` decimal(18,5) DEFAULT '0.00000',
  `adm_tipos_facturas_id` int DEFAULT NULL,
  `adm_usuarios_id` int NOT NULL,
  `adm_caja_id` int NOT NULL,
  `observacion` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `adm_enc_presupuesto_id` int DEFAULT NULL,
  `adm_enc_nota_entrega_id` int DEFAULT NULL,
  `aviso_cobro_id` int DEFAULT NULL,
  `adm_aviso_cobro` int DEFAULT NULL,
  `anulada` tinyint(1) DEFAULT '0',
  `aviso_cobro` tinyint DEFAULT NULL,
  `usuario_modificador` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'usuario que anula/edita la factura',
  `devuelto` decimal(30,12) NOT NULL,
  `motivoreimpresion` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `afecta_factura` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `rest_pedidos_id` int DEFAULT NULL,
  `fecha_hora` datetime DEFAULT NULL,
  `coo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `estatus_entrega` tinyint DEFAULT NULL,
  `fecha_entrega` datetime DEFAULT NULL,
  `fecha_vence` date DEFAULT NULL,
  `devolucion_parcial` tinyint(1) DEFAULT '0',
  `adm_series_facturas_id` int DEFAULT '0',
  `estatus_caja` tinyint DEFAULT '0',
  `fecha` date DEFAULT NULL,
  `estatus_verificacion` tinyint(1) DEFAULT NULL,
  `referencia_pedidos` int DEFAULT NULL,
  `verificacion_pago` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `adm_afiliados_id` int DEFAULT NULL,
  `tasa` decimal(30,12) DEFAULT '0.000000000000' COMMENT 'tasa aplicada al crear la factura',
  `igtf` decimal(30,12) DEFAULT '0.000000000000',
  `igtf_dolar` decimal(30,12) DEFAULT '0.000000000000',
  `si_devuelto` tinyint DEFAULT '0' COMMENT 'Si es 0= No devuelto; Si es 1= dev Total',
  `pago_comision` tinyint(1) DEFAULT NULL COMMENT '1=Pagada',
  `islr` decimal(30,12) DEFAULT '0.000000000000',
  `islr_dolar` decimal(30,12) DEFAULT '0.000000000000',
  `correlativo_apertura_caja` int DEFAULT '0',
  `ret_ae` decimal(30,3) DEFAULT '0.000',
  `ret_ae_dolar` decimal(30,3) DEFAULT '0.000',
  `cod_ret_ae` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `ret_iva` decimal(30,3) DEFAULT '0.000',
  `ret_iva_dolar` decimal(30,3) DEFAULT '0.000',
  `cod_ret_iva` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `porc_ret_iva` decimal(10,2) DEFAULT '0.00',
  `numero_reporte_z` int DEFAULT NULL,
  `fecha_at_ret_islr` datetime DEFAULT NULL,
  `fecha_at_ret_iva` datetime DEFAULT NULL,
  `fecha_at_ret_ae` datetime DEFAULT NULL,
  `segundo_cliente` int DEFAULT NULL,
  `fecha_comprobante_islr` date DEFAULT NULL,
  `fecha_comprobante_ret_iva` date DEFAULT NULL,
  `fecha_comprobante_ret_ae` date DEFAULT NULL,
  `documento_administrativo` enum('ADMINISTRATIVO','DIFERENCIAL CAMBIARIO') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `contabilizado` tinyint(1) DEFAULT NULL,
  `adm_empresa_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `clientes_id` (`adm_clientes_id`) USING BTREE,
  KEY `tipos_facturas_id` (`adm_tipos_facturas_id`) USING BTREE,
  KEY `usuarios_id` (`adm_usuarios_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb3 COMMENT='Encabezados de las facturas';
