/*!50003 CREATE*/ /*!50017 DEFINER=`ss_oficina`@`170.81.146.209`*/ /*!50003 TRIGGER `after_product_update` AFTER UPDATE ON `adm_movimiento_deposito` FOR EACH ROW BEGIN
    -- Verificar si la existencia ha cambiado
    IF NEW.existencia != OLD.existencia THEN
        -- Insertar un registro en la tabla de registro
        INSERT INTO cambio_existencias (adm_conceptos_id, adm_depositos_id, adm_movimiento_deposito_id, existencia_antes, nueva_existencia, existencia_comprometida_antes, nueva_existencia_comprometida, existencia_cambiada_a_woocomm)
        VALUES (NEW.adm_conceptos_id, NEW.adm_depositos_id, NEW.id, OLD.existencia, NEW.existencia, OLD.existencia_comprometida, NEW.existencia_comprometida, 0);
    END IF;
END */;;
