--
-- Table structure for table `adm_movimiento_inventario`
--

DROP TABLE IF EXISTS `adm_movimiento_inventario`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adm_movimiento_inventario` (
  `id` int NOT NULL AUTO_INCREMENT,
  `adm_conceptos_id` int NOT NULL,
  `fecha_at` date DEFAULT NULL,
  `adm_depositos_id` int NOT NULL,
  `tipo` varchar(4) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `origen` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `documento` int NOT NULL,
  `tercero` int DEFAULT NULL COMMENT 'clientes,proveedores,ajuste, recepcion',
  `cantidad` decimal(12,2) NOT NULL,
  `costo` decimal(30,12) DEFAULT NULL,
  `costo_dolar` decimal(12,2) DEFAULT '0.00',
  `venta` decimal(12,2) DEFAULT '0.00',
  `codigo_sucursal` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'codigo de la sede donde proviene la operacion (importante: agregar el codigo de la sucursal enviadora en el metodo de envio del erp)',
  `adm_color_id` int DEFAULT NULL,
  `adm_talla_id` int DEFAULT NULL,
  `info` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `adm_empresa_id` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=320 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
