DROP TABLE IF EXISTS `recurso_perfil`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recurso_perfil` (
  `id` int NOT NULL AUTO_INCREMENT,
  `recurso_id` int NOT NULL,
  `perfil_id` int NOT NULL,
  `recurso_perfil_at` datetime DEFAULT NULL,
  `recurso_perfil_in` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_recurso_perfil_recurso_idx` (`recurso_id`) USING BTREE,
  KEY `fk_recurso_perfil_perfil_idx` (`perfil_id`) USING BTREE,
  CONSTRAINT `recurso_perfil_ibfk_1` FOREIGN KEY (`perfil_id`) REFERENCES `perfil` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `recurso_perfil_ibfk_2` FOREIGN KEY (`recurso_id`) REFERENCES `recurso` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=38478 DEFAULT CHARSET=utf8mb3 COMMENT='Tabla que contiene los recursos del usuario en el sistema segun su perfl';
/*!40101 SET character_set_client = @saved_cs_client */;

